/* JOBA v1.1 — offline design prototype. All records are synthetic. No network, authentication, publishing or payment actions. */
const $=s=>document.querySelector(s);const logo='/assets/joba-logo-original.jpeg';
const icons={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3a6 6 0 0112 0v3M16 5a3 3 0 010 6M18 15a5 5 0 013 5"/>',search:'<circle cx="10" cy="10" r="6"/><path d="M15 15l6 6"/>',chev:'<path d="M8 5l7 7-7 7"/>',down:'<path d="M6 9l6 6 6-6"/>',shield:'<path d="M12 3l8 3v6c0 5-8 9-8 9s-8-4-8-9V6z"/><path d="M8 12l3 3 5-6"/>',briefcase:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12c6 3 12 3 18 0M10 13h4"/>',layers:'<path d="M12 3L2 8l10 5 10-5zM2 13l10 5 10-5M2 18l10 5 10-5"/>',file:'<path d="M14 3H5v18h14V8zM14 3v5h5M8 12h8M8 16h6"/>',credit:'<rect x="2" y="5" width="20" height="14" rx="2"/><path d="M2 10h20M6 15h4"/>',megaphone:'<path d="M3 10v5h5l10 5V4L8 10zM8 15l2 6M21 9v6"/>',bell:'<path d="M4 17h16l-2-3V9a6 6 0 00-12 0v5zM10 21h4"/>',chat:'<path d="M21 12a9 9 0 01-9 9H3l1.5-5A9 9 0 1121 12zM8 10h8M8 14h5"/>',globe:'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18"/>',settings:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="16" cy="17" r="3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v6l4 2"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 018 0v3M12 14v3"/>',check:'<path d="M5 12l4 4L19 6"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',filter:'<path d="M3 5h18l-7 8v7l-4-2v-5z"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12M7 10l5 5 5-5M4 16v5h16v-5"/>',upload:'<path d="M12 17V4M7 9l5-5 5 5M4 16v5h16v-5"/>',arrow:'<path d="M4 12h16M14 6l6 6-6 6"/>',eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/>',chart:'<path d="M4 3v18h18M8 16l5-6 4 3 5-8"/>',gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13M12 8C6 8 5 5 7 3c3-2 5 5 5 5s2-7 5-5c2 2 1 5-5 5"/>',star:'<path d="M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="2"/><path d="M3 18l6-6 4 4 3-4 5 6"/>',archive:'<path d="M4 8v13h16V8M2 3h20v5H2zM9 13h6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M20 12A8 8 0 006 6M4 12a8 8 0 0014 6"/>',logout:'<path d="M10 3H4v18h6M8 12h14M17 7l5 5-5 5"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};
const ic=(name)=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.grid}</svg>`;
const badge=(s,c='')=>`<span class="badge ${c}">${s}</span>`;const btn=(s,act='preview',cls='',icon='')=>`<button class="${cls}" data-action="${act}">${icon?ic(icon):''}${s}</button>`;
const card=(title,body,extra='',cls='')=>`<section class="card ${cls}">${title?`<div class="cardhead"><h2>${title}</h2>${extra}</div>`:''}<div class="cardbody">${body}</div></section>`;
const table=(heads,rows)=>`<div class="tablewrap"><table><thead><tr>${heads.map(s=>`<th>${s}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(s=>`<td>${s}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
const tablecard=(title,heads,rows,extra='',foot='Показано '+rows.length+' записей · Все данные демонстрационные')=>`<section class="card"><div class="cardhead"><h2>${title}</h2>${extra}</div>${table(heads,rows)}<div class="cardfoot"><span>${foot}</span><span>‹ &nbsp; <b>1</b> &nbsp; 2 &nbsp; 3 &nbsp; ›</span></div></section>`;
const note=(text,type='',icon='info')=>`<div class="note ${type}">${ic(icon)}<div>${text}</div></div>`;
const metric=(label,n,change,sub='',icon='')=>`<section class="card metric"><div class="metric-label">${label}${icon?ic(icon):''}</div><div class="metric-num">${n}</div><div class="metric-trend">${change}<span>${sub}</span></div></section>`;
const person=(name,id,initials='ДА')=>`<div class="cellperson"><span class="avatar">${initials}</span><div><b>${name}</b><span class="sub">${id}</span></div></div>`;
const info=(a,b)=>`<div class="info-row"><span>${a}</span><b>${b}</b></div>`;
const field=(label,value,type='text',help='',wide=false)=>`<div class="formfield ${wide?'wide':''}"><label>${label}</label>${type==='select'?`<select aria-label="${label}">${value.split('|').map(x=>`<option>${x}</option>`).join('')}</select>`:type==='textarea'?`<textarea aria-label="${label}" rows="3">${value}</textarea>`:`<input aria-label="${label}" type="${type}" value="${value}">`}${help?`<small>${help}</small>`:''}</div>`;
const tab=(items,active)=>`<div class="tabs">${items.map(([label,route,count])=>`<a href="#${route}" class="${route===active?'active':''}">${label}${count?`<span>${count}</span>`:''}</a>`).join('')}</div>`;
const filters=(placeholder='Поиск по ID',extra='')=>`<div class="filters"><input aria-label="Поиск" placeholder="${placeholder}"><select aria-label="Страна"><option>Все страны</option><option>Казахстан</option><option>Кыргызстан</option><option>Россия</option><option>Беларусь</option></select>${extra}${btn('Фильтры','filters','','filter')}</div>`;
const toggle=(on=true,locked=false)=>`<button class="switch ${on?'on':''} ${locked?'lock':''}" role="switch" aria-checked="${on}" aria-label="Переключить демо-настройку" ${locked?'disabled':''} data-action="toggle"></button>`;
const stepper=(labels,active=1)=>`<div class="stepper">${labels.map((x,i)=>`<div class="step ${i<active?'done':i===active?'current':''}"><i>${i<active?'✓':i+1}</i>${x}</div>`).join('')}</div>`;
const event=(title,desc,time)=>`<div class="event"><b>${title}</b><p>${desc}</p><time>${time}</time></div>`;
const chart=`<svg class="chart" viewBox="0 0 640 185" role="img" aria-label="Демонстрационная динамика: число опубликованных заказов растет за неделю"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#245BDB" stop-opacity=".13"/><stop offset="1" stop-color="#245BDB" stop-opacity=".01"/></linearGradient></defs><g stroke="#EBEFF6" stroke-width="1"><path d="M34 20H620M34 62H620M34 104H620M34 146H620"/></g><g><text x="0" y="24">240</text><text x="0" y="66">160</text><text x="7" y="108">80</text><text x="15" y="150">0</text></g><path d="M35 126C74 126 97 82 132 89S206 116 229 81S299 100 328 65S392 76 426 58S481 67 523 39S582 49 620 22V146H35Z" fill="url(#area)"/><path d="M35 126C74 126 97 82 132 89S206 116 229 81S299 100 328 65S392 76 426 58S481 67 523 39S582 49 620 22" fill="none" stroke="#245BDB" stroke-width="2.5"/><path d="M35 138C88 127 107 126 132 132S209 111 229 120S302 105 328 112S399 86 426 95S494 83 523 92S587 66 620 77" fill="none" stroke="#AABAD4" stroke-width="2" stroke-dasharray="4 4"/><g><text x="35" y="178">6 окт</text><text x="130" y="178">7 окт</text><text x="230" y="178">8 окт</text><text x="328" y="178">9 окт</text><text x="425" y="178">10 окт</text><text x="523" y="178">11 окт</text><text x="585" y="178">12 окт</text></g></svg>`;
const routes={};const add=(key,id,title,subtitle,body,section='Операции',actions='')=>routes[key]={key,id,title,subtitle,body,section,actions};
