add('case','A06','Дело CASE-DEMO-087','Портфолио · PRJ-DEMO-042 / ревизия 3 · назначено Алине В.',()=>`${stepper(['Открыто','Проверка','Решение','Апелляция'],1)}<div class="grid split"><div class="stack">${card('Материал и основание',`<div class="row">${badge('Контактные данные на фото','orange')}<span class="tiny muted">Снимок rev. 3 · неизменяемый</span></div><h3 style="margin:17px 0 7px">Кухонный гарнитур после сборки</h3><p class="tiny muted">На фотографии обнаружен фрагмент контактной информации. Текстовый фильтр не анализирует изображения.</p><div class="artwork" style="height:190px;margin-top:17px"></div><div class="row" style="margin-top:12px"><span class="tiny muted">Фото 2 из 4 · безопасная производная · DEMO</span>${btn('Материалы','preview','small','eye')}</div>`)}${card('Объяснение пользователя',`<p class="quote">«На коробке был номер магазина. Готов убрать его и загрузить исправленное фото».</p><p class="helptext">Цитата предоставлена для демонстрации. Поддержка и апелляция не запускают повторную автоблокировку за цитируемый текст.</p>`)}</div><div class="stack">${card('Решение по ревизии',`<div class="stack">${field('Результат','Запросить исправление|Одобрить|Отклонить|Скрыть проект','select')}${field('Причина для пользователя','Уберите контактные данные с фотографии и отправьте новую ревизию.','textarea')}${field('Правило','Контакты и персональные данные · v1.1','select')}<label class="check"><input type="checkbox" checked> Рассмотрена текущая ревизия 3</label>${btn('Предпросмотр решения','publish','primary')}</div>`)}${card('История дела',`<div class="timeline">${event('Назначено reviewer','Алина В. · страна KZ','12 окт · 11:35 UTC')}${event('Поступило объяснение','От владельца проекта','12 окт · 10:20 UTC')}${event('Создано дело','Жалоба на фото проекта','11 окт · 16:20 UTC')}</div>`)}${note('Апелляцию не может завершить автор обжалуемого решения.','', 'shield')}</div></div>`,'Модерация');
add('dictionary','A18','Словари запрещенных слов','Версионированные правила для серверных поверхностей. Совпадение отправляет материал в карантин.',()=>`${tab([['Очередь','moderation'],['Словари','dictionary'],['Черный список','blacklist']], 'dictionary')}<div class="grid split"><div class="stack">${filters('Найти правило или фразу',`<select aria-label="Язык"><option>Русский · ru</option><option>Қазақша · kk</option></select>`)}${tablecard('Правила · черновик v9',['Правило','Тип','Поверхности','Действие','Статус'],[['[демо-фраза 01]','Точная фраза','Профили, заказы',badge('Auto-hold','orange'),badge('Активно','green')],['[демо-фраза 02]','Слово','Портфолио, отзывы',badge('Quarantine','orange'),badge('Активно','green')],['[демо-фраза 03]','Точная фраза','Публичный текст',badge('На review','blue'),badge('Черновик')],['[демо-исключение]','Исключение','Все указанные',badge('Пропустить'),badge('Активно','green')]],btn('Добавить правило','preview','small','plus'))}${note('Regex не поддерживается. Жалобы, апелляции и поддержка проверяются отдельной ручной очередью, чтобы цитирование не создавало повторный бан.')}</div><div class="stack">${card('Параметры версии',`${info('Страна / язык','KZ / ru')}${info('Активная версия','v8 · 01.10.2026')}${info('Черновик','v9 · 3 изменения')}${info('Auto-hold','24 часа · DEMO-параметр')}${info('Дальнейшее решение','Только human review')}`)}${card('Проверка перед публикацией',`<p class="tiny muted">Dry-run покажет количество совпадений и исключений на обезличенной выборке. Публикация фиксирует автора и причину.</p>${btn('Запустить dry-run','dictionary-dryrun','primary','eye')}`)}</div></div>`,'Модерация',btn('Сохранить','save','','check'));
add('dictionary-dryrun','A18.dryrun','Проверка словаря v9','Обезличенная тестовая выборка · 10 000 материалов · DEMO.',()=>`${note('Dry-run не меняет опубликованные материалы, санкции или права пользователей.')}<div class="grid cols4">${metric('Проверено материалов','10 000','100%','выборки')}${metric('Совпадения','82','0,82%','от выборки')}${metric('Исключения','11','Не попадут','в карантин')}${metric('Изменение к v8','+14','Проверить','вручную')}</div><div class="mt">${tablecard('Предпросмотр результатов',['Правило','Поверхность','Совпадений','Исключений','Ожидаемое действие'],[['[демо-фраза 01]','Профиль','36','5','Карантин текущей ревизии'],['[демо-фраза 02]','Портфолио','24','4','Карантин + временный hold'],['[демо-фраза 03]','Заказ','22','2','Ручная проверка']])}</div><div class="grid cols2 mt">${card('Публикация версии',`<div class="stack">${field('Причина изменения','Уточнение правил публичных контактных данных','textarea')}${field('Начало действия','2026-10-13T09:00','datetime-local','Asia/Almaty · UTC+5')}${btn('Предпросмотр публикации','publish','primary')}</div>`)}${card('Важные ограничения',`<div class="timeline">${event('Только актуальная ревизия','Старое совпадение не блокирует исправленный материал.','')}${event('Конечный срок auto-hold','Не превращается автоматически в постоянный черный список.','')}${event('Повторная проверка','До публикации на каждой серверной поверхности.','')}</div>`)}</div>`,'Модерация');
add('blacklist','A03.blacklist / FR-042','Черный список','Внутренние ограничения по делу. Нет публичного списка обвинений.',()=>`${tab([['Очередь','moderation'],['Словари','dictionary'],['Черный список','blacklist']], 'blacklist')}${filters('User ID или номер дела')} ${tablecard('Записи ограничений',['Пользователь','Дело / категория','Scope','Срок','Состояние',''],[[person('Мария Н.','USR-DEMO-1015','МН'),'CASE-DEMO-064<span class="sub">Повторное нарушение правил</span>','Новые коммерческие действия','До 18 окт · 12:00',badge('Активно','red'),btn('Пересмотреть','blacklist-detail','small')],[person('Илья В.','USR-DEMO-0884','ИВ'),'CASE-DEMO-051<span class="sub">Нарушение правил контента</span>','Публикация профиля','Истек 10 окт',badge('Истекло'),btn('История','preview','small')],[person('Ольга К.','USR-DEMO-0726','ОК'),'CASE-DEMO-030<span class="sub">Решение апелляции</span>','Ограничение снято','8 окт · 10:30',badge('Отменено','green'),btn('История','preview','small')]])}<div class="grid cols2 mt">${card('Что сохраняется',`<p class="tiny muted">Поддержка, апелляция, privacy, оплаченная история и безопасное завершение действующих заказов остаются доступны.</p>`)}${card('Не путать с удалением',`<p class="tiny muted">Удаление аккаунта выполняется отдельным privacy-процессом, с re-auth, retention и вторым подтверждением.</p><a class="tiny" href="#privacy">Privacy-очередь →</a>`)}</div>`,'Модерация',btn('Создать ограничение','blacklist-detail','primary','plus'));
add('blacklist-detail','A03.blacklist.detail','Новое ограничение','Решение старшего модератора · DEMO · preview перед применением.',()=>`<div class="grid split">${card('Основание и область',`<div class="formgrid">${field('Пользователь','USR-DEMO-1015')}${field('Связанное дело *','CASE-DEMO-064')}${field('Категория','Нарушение правил контента','select')}${field('Область','Новые коммерческие действия','select')}${field('Начало','2026-10-12T13:30','datetime-local')}${field('Окончание','2026-10-18T12:00','datetime-local','UTC · срок обязателен либо обоснование постоянного')}${field('Причина для пользователя *','Повторное размещение запрещенного содержания. Решение можно обжаловать через поддержку.','textarea','',true)}${field('Доказательства','EVID-DEMO-021 · snapshot rev. 3','text','',true)}</div>`)}${card('Последствия',`${note('Будут ограничены новые поиск, публикация и отклики. Поддержка, privacy и безопасное завершение активных заказов сохраняются.','warn')}${info('Затронут аккаунт','1 · USR-DEMO-1015')}${info('Активные заказы','2 · safety scope сохраняется')}${info('Уведомление','Причина + путь апелляции')}${info('Проверка роли','senior_moderator · KZ')}${btn('Предпросмотр решения','publish','primary')}`)}</div>`,'Черный список');
add('verification','A07','Проверка личности','Очередь обязательной проверки исполнителей. В списке только минимальные сведения.',()=>`${filters('Verification ID или user ID',`<select aria-label="Статус"><option>Ожидают проверки</option><option>Нужна повторная отправка</option></select>`)}${note('Исходники документов не доступны обычной роли администратора. Защищенный просмотр требует verification.read_document, MFA и причины.','', 'lock')}${tablecard('Заявки исполнителей',['Заявка','Пользователь','Страна / тип','Ревизия','Ожидание','Статус',''],[['VERIFY-DEMO-081',person('Тимур С.','USR-DEMO-1108','ТС'),'KZ · удостоверение','rev. 2','21 час',badge('На проверке','orange'),'<a href="#verification-detail">Открыть →</a>'],['VERIFY-DEMO-082',person('Алексей Р.','USR-DEMO-1124','АР'),'KZ · паспорт','rev. 1','18 часов',badge('На проверке','orange'),'<a href="#verification-detail">Открыть →</a>'],['VERIFY-DEMO-079',person('Елена Т.','USR-DEMO-1088','ЕТ'),'KZ · удостоверение','rev. 3','4 часа',badge('Повторная подача','blue'),'<a href="#verification-detail">Открыть →</a>'],['VERIFY-DEMO-075',person('Илья В.','USR-DEMO-1071','ИВ'),'KZ · паспорт','rev. 1','2 часа',badge('Нужны исправления'),'История']])}<div class="grid cols2 mt">${card('Сроки и удаление',`${info('Предлагаемый SLA','1 рабочий день')}${info('Исходник после решения','30 дней · требует legal approval')}${info('Незавершенное дело','14 дней от первой загрузки')}`)}${card('Ограниченный результат',`<p class="tiny muted">Храним минимальный результат, reference и срок проверки. Значок подтверждает факт проверки документа, не качество услуг или отсутствие мошенничества.</p>`)}</div>`,'Операции');
add('verification-detail','A07.guard','Заявка VERIFY-DEMO-081','USR-DEMO-1108 · KZ · удостоверение личности · текущая ревизия 2.',()=>`<div class="grid split"><div class="stack">${card('Защищенный документ',`<div class="empty" style="padding:55px 25px">${ic('lock')}<h2>Просмотр ограничен</h2><p>Исходник хранится отдельно. Для открытия нужны специальное право, MFA и служебная причина.</p>${btn('Запросить защищенный просмотр','id-auth','primary','eye')}</div>`)}${card('Метаданные заявки',`<div class="kv"><div><label>Статус</label><b>pending_review</b></div><div><label>Актуальная ревизия</label><b>2 · поступила 11 октября</b></div><div><label>Проверка файла</label><b>Scan passed · MIME / размеры проверены</b></div><div><label>Регион хранения</label><b>KZ · приватное хранилище</b></div></div>`)}</div><div class="stack">${card('Контроль доступа',`${info('Текущая роль','country_admin')}${info('Просмотр статуса','Разрешен')}${info('Просмотр исходника','Требуется verification permission')}${info('Чувствительный аудит','На каждый просмотр')}${info('Временная ссылка','60 секунд · без публичного кэша')}`)}${note('Проверка документа обязательна для исполнительских действий. Заказчик, поддержка и privacy остаются доступны при отказе.','warn')}${card('История',`<div class="timeline">${event('Новая ревизия 2','Файл прошел техническую проверку','11 окт · 16:20 UTC')}${event('Запрошена повторная подача','Нечитаемая область документа','10 окт · 12:40 UTC')}</div>`)}</div></div>`,'Документы');
add('id-auth','A07.authorization','Разрешение защищенного просмотра','Демонстрация проверки полномочий. Реальный документ в макеты не включен.',()=>`<div style="max-width:620px;margin:15px auto">${card('Служебная цель',`${note('Будет создана запись sensitive-read audit. Доступ к исходнику ограничен 60 секундами.','warn','lock')}<div class="stack">${field('Заявка / ревизия','VERIFY-DEMO-081 / rev. 2')}${field('Причина *','Проверка обязательного документа исполнителя','textarea')}${field('Полномочие','verification_reviewer · KZ','select')}${field('Повторная аутентификация','MFA подтверждена · DEMO','select')}<label class="check"><input type="checkbox" checked> Открываю только материал текущей заявки</label>${btn('Открыть демо-документ','verification-review','primary','eye')}</div>`)}</div>`,'Документы');
add('verification-review','A07.review','Проверка ревизии 2','Защищенный режим · VERIFY-DEMO-081 · AUD-DEMO-902 · DEMO.',()=>`${note('<b>Временный просмотр: 00:52.</b> Передача и скачивание исходника недоступны. Решение относится только к открытой ревизии 2.','warn','lock')}<div class="grid split">${card('Демонстрационный материал',`<div class="fakeid"><h2>DEMO · NOT A DOCUMENT</h2><p>Нет настоящего паспорта, номера, фотографии или персональных данных</p></div><div class="row" style="margin-top:17px"><span class="tiny muted">Страница 1 из 2 · защищенная производная</span>${btn('Следующая','preview','small','chev')}</div><p class="helptext" style="margin-top:18px">Здесь в продукте отображается разрешенный материал. Дизайн не воспроизводит настоящий или правдоподобный документ личности.</p>`)}${card('Результат проверки',`<div class="stack"><label class="check"><input type="checkbox"> Документ читаем и соответствует допустимому типу</label><label class="check"><input type="checkbox"> Минимальные данные сопоставлены по политике страны</label><label class="check"><input type="checkbox"> Возрастной допуск 18+ подтвержден</label>${field('Решение','Выберите результат|Одобрить|Отклонить|Запросить повторно','select')}${field('Причина *','','textarea')}${field('Версия политики','KZ-ID-policy-v1 · DEMO')}${btn('Предпросмотр решения','publish','primary')}</div><p class="helptext" style="margin-top:15px">Повторная загрузка пользователя сделает эту ревизию устаревшей. Перед решением сервер проверит current_revision.</p>`)}</div>`,'Документы',btn('Закрыть материал','verification-detail','','lock'));
add('portfolio','A05.portfolio / FR-040','Портфолио исполнителей','Проекты, фотографии и ревизии. Публикация требует безопасного фото и действующего права.',()=>`${filters('Название проекта, user ID или project ID',`<select aria-label="Статус"><option>На проверке</option><option>Опубликовано</option><option>Архив</option></select>`)}<div class="grid cols3">${[['Кухонный гарнитур','Данияр А.','PRJ-DEMO-042','Ревизия 3',false],['Сборка стеллажа','Алексей Р.','PRJ-DEMO-051','Ревизия 1',true],['Рабочее место дома','Мария Н.','PRJ-DEMO-064','Ревизия 2',false]].map(([title,owner,id,rev,two])=>`<article class="portfolio-item"><div class="artwork ${two?'second':''}"></div><div class="cardbody"><div class="row"><span class="tiny muted">${id}</span>${badge('На проверке','orange')}</div><h3 style="margin:12px 0 6px">${title}</h3><p>${owner} · DEMO<br>${rev} · 4 безопасных фото</p><div class="notice-slim">Связан с завершенным заказом JOBA</div><a href="#case" class="tiny" style="display:block;margin-top:16px">Проверить ревизию →</a></div></article>`).join('')}</div><div class="grid cols2 mt">${card('Правила публикации',`${info('Минимум','1 проверенное фото')}${info('Право доступа','Активно · executor_verified')}${info('Проверка','Текст + safe upload pipeline')}${info('Старая версия','Остается видимой до решения по политике')}`)}${card('Авторство и приватность',`<p class="tiny muted">Автор подтверждает права на фото. Чужие адреса, контакты и изображения клиентов без основания запрещены. Значок связи с заказом не доказывает авторство или качество.</p><p class="helptext">Графические композиции в макете — условные демо-обложки, не реальные работы.</p>`)}</div>`,'Операции');
add('support','A21','Поддержка','Встроенные приватные чаты · 23 открытых обращения · 7 без назначения.',()=>`<div class="chatlayout"><aside class="chatlist"><div class="cardhead"><h3>Очередь</h3>${badge('23','blue')}</div><div style="padding:12px"><input style="width:100%;font-size:10px" placeholder="Ticket или user ID" aria-label="Поиск обращения"></div><div class="chatrow active"><div class="row"><b>SUP-DEMO-042</b><span class="tiny muted">12:40</span></div><p>Данияр А. · Вопрос о подписке</p>${badge('Ждет поддержки','orange')}</div><div class="chatrow"><div class="row"><b>REC-DEMO-019</b><span class="tiny muted">12:28</span></div><p>До входа · Восстановление доступа</p><a href="#support-recovery" class="tiny">Открыть →</a></div><div class="chatrow"><div class="row"><b>SUP-DEMO-041</b><span class="tiny muted">11:55</span></div><p>Анна К. · Изменение заказа</p>${badge('Назначено','blue')}</div><div class="chatrow"><b>SUP-DEMO-040</b><p>Сауле Б. · Проверка документа</p>${badge('Ждет пользователя')}</div></aside><section class="conversation"><header class="chathead"><div class="row"><div><h3>Вопрос о подписке</h3><span class="tiny muted">Данияр А. · USR-DEMO-1042 · KZ</span></div>${btn('Завершить','preview','small')}</div></header><div class="messages"><div class="tiny muted" style="text-align:center">12 октября 2026 · все сообщения DEMO</div><div class="message">Подписка активна, но после смены телефона появилось предложение оплатить снова.<small>Данияр А. · 12:38</small></div><div class="message support">Здравствуйте! Проверим статус покупки. Вы вошли в тот же аккаунт JOBA на новом устройстве?<small>Поддержка · Мария Д. · 12:39 · доставлено</small></div><div class="message">Да, тот же номер. В приложении вижу дату до 2 ноября.<small>Данияр А. · 12:40</small></div><div class="message note-msg"><b>Внутренняя заметка · только staff ACL</b><p style="margin:6px 0 0">Проверить восстановление TX-DEMO-101. Не запрашивать пароль или данные карты.</p><small>Мария Д. · 12:41</small></div></div><div class="composer"><div class="badges" style="margin-bottom:9px">${badge('Ответ пользователю','blue')}${badge('Внутренняя заметка')}</div><textarea aria-label="Ответ в поддержку" placeholder="Ответ от имени поддержки…"></textarea><div class="row"><span class="tiny muted">Без паролей, кодов и документов</span>${btn('Отправить · DEMO','send-support','primary')}</div></div></section><aside class="chatdetail"><h3>Обращение</h3>${info('Статус','waiting_support')}${info('Ответственный','Мария Д.')}${info('Страна','Казахстан')}${info('Создано','12 окт · 12:38')}${info('Роль','support_agent')}<h3 style="margin-top:25px">Связанные объекты</h3><a class="tiny" href="#user-detail">USR-DEMO-1042 →</a><p class="tiny muted" style="margin-top:10px">TX-DEMO-101 · статус без платежных секретов</p><div class="notice-slim" style="margin-top:25px">Поддержка доступна без подписки и при ограничениях аккаунта.</div></aside></div>`,'Операции');
add('support-recovery','A21.thread','Восстановление доступа','REC-DEMO-019 · pre-login обращение · регион KZ · личность еще не подтверждена.',()=>`${note('<b>Ограниченный анонимный чат.</b> Только текст. Введенный номер не доказывает владение аккаунтом и не открывает старую историю.','warn','lock')}<div class="grid split">${card('Чат до входа',`<div class="stack"><div class="message">Не помню пароль. Как восстановить доступ?<small>Посетитель · 12:28 UTC</small></div><div class="message support">Поможем разобраться. Не присылайте пароль, коды или документы в этот чат. Восстановление выполняется по утвержденной процедуре проверки владения.<small>Поддержка · 12:31 UTC</small></div><div class="notice-slim">Пока D17 не утвержден, оператор может только зафиксировать обращение и объяснить следующий разрешенный шаг.</div><textarea aria-label="Ответ" rows="4" placeholder="Написать ответ…"></textarea><div class="row"><span class="tiny muted">Вложения недоступны</span>${btn('Отправить · DEMO','send-support','primary')}</div></div>`)}${card('Безопасность recovery',`${info('Видимость','Только этот ticket')}${info('Capability','Секрет не отображается')}${info('Срок доступа','72 часа · предложение')}${info('Связь с аккаунтом','Не установлена')}${info('Ownership policy D17',badge('Ожидает утверждения','orange'))}${note('Не подтверждать наличие аккаунта по номеру. Новый ticket не наследует старые заказы, чаты или документы.','', 'shield')}`)}</div>`,'Поддержка');
add('pricing','A09 / A22.prices','Каталог цен','Один источник цен для подписки и продвижения. Все суммы ниже — демонстрационные, не утвержденные тарифы.',()=>`${tab([['Цены и SKU','pricing'],['Промо 0 до даты','promo'],['Продвижение','boosts']], 'pricing')}${filters('План, SKU или price version',`<select aria-label="Продукт"><option>Все продукты</option><option>Подписка</option><option>Продвижение</option></select>`)}${tablecard('Актуальные версии',['Продукт','Страна','Цена · DEMO','Период','Provider / SKU','Синхронизация',''],[['JOBA Доступ','KZ','500 ₸','Месяц','Store DEMO<span class="sub">kz_access_month_demo</span>',badge('Подтверждено','green'),btn('Версия','preview','small')],['JOBA Доступ','KG','490 KGS','Месяц','Store DEMO<span class="sub">rs_access_month_demo</span>',badge('Черновик'),btn('Открыть','preview','small')],['Продвижение карточки','KZ','200 ₸','7 суток','Store DEMO<span class="sub">kz_boost_week_demo</span>',badge('Подтверждено','green'),'<a href="#boosts">Настроить →</a>'],['Продвижение карточки','KZ','650 ₸','Календарный месяц','Store DEMO<span class="sub">kz_boost_month_demo</span>',badge('Ожидает SKU','orange'),btn('Проверить','preview','small')],['JOBA Доступ','RU','—','Месяц','Канал не подтвержден',badge('Продажа закрыта','red'),'<a href="#countries">Блокер →</a>']])}<div class="grid cols2 mt">${card('Изменение цены',`<p class="tiny muted">Новые покупатели и существующие когорты обрабатываются отдельно. Цена становится доступной только после подтвержденной синхронизации продукта магазина.</p><div class="notice-slim">Нет комиссии с выполненных заказов в первом релизе.</div>`)}${card('Запланированное промо',`<div class="row"><div><h3>0 ₸ до 31 октября</h3><p class="tiny muted" style="margin-top:5px">KZ · новые пользователи · DEMO</p></div>${badge('Черновик','blue')}</div><a class="tiny" href="#promo" style="display:block;margin-top:12px">Проверить границу и следующую цену →</a>`)}</div>`,'Монетизация',btn('Новая версия цены','preview','primary','plus'));
add('promo','A09.promo','Промо-период подписки','Временный бесплатный доступ до выбранной даты. Подписка остается базовым способом.',()=>`${stepper(['Черновик','Проверка','Предпросмотр','Расписание'],0)}<div class="grid split">${card('Параметры промо',`<div class="formgrid">${field('План','JOBA Доступ','select')}${field('Страна','Казахстан · KZ','select')}${field('Аудитория','Новые пользователи|Все пользователи|Существующие','select')}${field('Роли','Обе роли','select')}${field('Начало','2026-10-15T00:00','datetime-local')}${field('Бесплатно по дату включительно','2026-10-31','date')}${field('Часовой пояс','Asia/Almaty','select')}${field('Цена в промо','0 ₸ · DEMO')}${field('Следующий тариф','500 ₸ / месяц · DEMO')}${field('Проверенный SKU','kz_access_month_demo')}${field('Условия для пользователя','Доступ бесплатно до 31 октября включительно. Затем потребуется выбранный вами способ доступа. Автоматического списания нет.','textarea','',true)}</div>`)}<div class="stack">${card('Вычисленная граница',`<h2 style="font-size:23px">1 ноября · 00:00</h2><p class="tiny muted" style="margin-top:6px">Asia/Almaty · UTC+5</p>${info('promo_end_exclusive','2026-10-31 19:00 UTC')}${info('Следующая цена','500 ₸ / месяц · DEMO')}${info('Источник бесплатного права','Серверный promo-entitlement')}${info('Перекрывающиеся промо','Не найдены')}`)}${note('После промо деньги не списываются автоматически. Нужны отдельный выбор и законный checkout пользователя.','warn')}${card('Проверка влияния',`<p class="tiny muted">Оплаченные сроки не сокращаются. Активные заказы сохраняют safety scope. Повторное получение не продлевает фиксированную границу.</p>${btn('Предпросмотр промо','promo-preview','primary','eye')}`)}</div></div>`,'Каталог цен',btn('Сохранить','save','','check'));
add('promo-preview','A09.preview','Предпросмотр промо','PROMO-DEMO-004 · KZ · новые пользователи · обе роли.',()=>`${note('Публикация требует проверки следующего платного продукта и второго уполномоченного сотрудника.','warn')}<div class="grid cols2">${card('Что увидит пользователь',`<div style="background:#F3F6FD;border-radius:12px;padding:25px"><span class="eyebrow">JOBA ДОСТУП</span><h2 style="font-size:28px;margin-top:10px">0 ₸ до 31 октября</h2><p class="muted" style="margin-top:8px">Затем 500 ₸ / месяц · DEMO</p><div class="badges" style="margin:15px 0">${badge('Для обеих ролей','blue')}${badge('До 01.11, 00:00 · Алматы')}</div><p class="tiny muted">По окончании промо выберите доступный способ продолжения. Списание без вашего согласия не произойдет.</p></div>`)}${card('Проверки',`${info('SKU следующего тарифа',badge('Подтвержден','green'))}${info('Конфликт промо',badge('Нет','green'))}${info('Часовой пояс','Asia/Almaty · UTC+5')}${info('UTC-граница','31.10.2026 · 19:00')}${info('Существующие платные права','Сохраняются')}${info('Второе подтверждение',badge('Ожидается','orange'))}${field('Причина публикации','Промо запуска в Казахстане · DEMO','textarea')}${btn('На согласование · DEMO','publish','primary')}`)}</div><div class="mt">${note('Остановка промо прекращает выдачу новых grants, но сохраняет ранее обещанный срок. Магазинный SKU не переписывается на произвольный ноль.')}</div>`,'Промо');
add('rewarded','A16.rewarded','Rewarded-доступ','Конфигурация обещанной награды и проверка callback. Предложенные параметры требуют утверждения.',()=>`${note('Rewarded выключен: нет подтверждения совместимости полного core-paywall с правилами выбранного провайдера.','warn','shield')}<div class="grid split">${card('Политика награды · черновик',`<div class="formgrid">${field('Модель','Временный доступ|Кредиты действий','select')}${field('Награда · DEMO','24 часа')}${field('Scope роли','Исполнитель','select')}${field('Capability','search_full, send_offer')}${field('Cooldown · DEMO','30 минут')}${field('Максимум в сутки · DEMO','3 награды')}${field('Накопление вперед · DEMO','72 часа')}${field('Поздняя сверка · предложение','72 часа')}</div><p class="helptext" style="margin-top:16px">Пользователь видит награду и условия до запуска. Просмотр баннера никогда не создает grant.</p>`)}${card('Надежная выдача',`<div class="timeline">${event('Обещание зафиксировано','Session хранит snapshot версии, награды и роли.','1 · Start')}${event('Callback подтвержден','Проверена подпись и связь с аккаунтом.','2 · SSV')}${event('Grant выдан один раз','Idempotency защищает от повторной награды.','3 · Ledger')}${event('Задержка или no-fill','Понятное объяснение, cooldown и доступная подписка.','4 · Recovery')}</div>`)}</div><div class="mt">${tablecard('Демо-сессии',['Session','Snapshot','Состояние','Grant','Повтор'],[['ADS-DEMO-101','v11 · 24 ч · исполнитель',badge('Подтверждено','green'),'ENT-DEMO-211','Отклонен как duplicate'],['ADS-DEMO-102','v11 · 24 ч · заказчик',badge('Ожидает callback','orange'),'Не выдан','Сверка запланирована'],['ADS-DEMO-103','v11 · 24 ч · исполнитель',badge('No-fill'),'Не выдан','После cooldown']])}</div>`,'Монетизация',btn('Сохранить','save','','check'));
add('campaigns','A10','Баннерные кампании','Креативы, разрешенные размещения и лимиты. Включение баннеров не меняет подписку или rewarded.',()=>`${filters('Название кампании или creative ID')}${tablecard('Кампании',['Кампания','Размещение','Срок','Лимит · DEMO','Состояние',''],[['Осенний запуск JOBA','Каталог · inline','15–31 окт','1 показ / 3 экрана',badge('Черновик'),'<a href="#banner-detail">Открыть →</a>'],['Сервисы рядом','Главная · нижний блок','1–20 окт','3 показа / день',badge('На проверке','orange'),'<a href="#banner-detail">Открыть →</a>'],['Локальный партнер','Каталог · разделитель','1–10 окт','Бюджет: 20 000 ₸',badge('Завершена','green'),'<a href="#archive">Архив →</a>']])}<div class="grid cols2 mt">${card('Разрешенное inline-размещение',`<div class="bannerpreview"><div class="letter-icon">J</div><div><small>РЕКЛАМА · DEMO</small><b>Услуги рядом с вами</b><p>Проверенный локальный партнер</p></div></div><p class="helptext" style="margin-top:15px">Слот не перекрывает действие, поле или клавиатуру. При no-fill компоновка меняется безопасно.</p>`)}${card('Исключенные экраны',`<div class="badges">${['Чат','Оплата','Создание заказа','Выбор исполнителя','Документы','Поддержка','Privacy'].map(x=>badge(x)).join('')}</div><p class="tiny muted" style="margin-top:16px">Не использовать фальшивые кнопки приложения и не выдавать право за обычный баннерный показ.</p>`)}</div>`,'Реклама',btn('Новая кампания','banner-detail','primary','plus'));
